package com.akshay.stockflow.warehouse;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class WarehouseAndProcurementIntegrationTests {
@Autowired MockMvc mvc; @Autowired ObjectMapper mapper;
private String adminToken() throws Exception {String body=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"admin@stockflow.local\",\"password\":\"ChangeMe123!\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return mapper.readTree(body).get("accessToken").asText();}
@Test void warehouseTransferMovesStockAndCreatesDestinationBalance() throws Exception {String token=adminToken();String created=mvc.perform(post("/api/products").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Transfer Test Widget\",\"sku\":\"TRANSFER-TEST-01\",\"category\":\"Test\",\"warehouse\":\"Test Source\",\"quantity\":10,\"reorderLevel\":2,\"unitPrice\":25}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();long productId=mapper.readTree(created).get("id").asLong();mvc.perform(post("/api/warehouse-transfers").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"productId\":"+productId+",\"destinationWarehouse\":\"Test Destination\",\"quantity\":4}")).andExpect(status().isCreated()).andExpect(jsonPath("$.quantity").value(4));mvc.perform(get("/api/warehouse-transfers").header("Authorization","Bearer "+token)).andExpect(status().isOk());}
@Test void purchaseOrderCanBeReceivedOnlyOnce() throws Exception {String token=adminToken();String created=mvc.perform(post("/api/purchase-orders").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"supplierId\":1,\"lines\":[{\"productId\":1,\"quantity\":3,\"unitCost\":150}]}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();long id=mapper.readTree(created).get("id").asLong();mvc.perform(post("/api/purchase-orders/"+id+"/receive").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("RECEIVED"));mvc.perform(post("/api/purchase-orders/"+id+"/receive").header("Authorization","Bearer "+token)).andExpect(status().isConflict());}
@Test void employeeRequestCanBeApprovedIntoPurchaseOrder() throws Exception {String admin=adminToken();mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"requester@example.test\",\"password\":\"LongPassword123!\",\"fullName\":\"Requester\"}")).andExpect(status().isCreated());String login=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"requester@example.test\",\"password\":\"LongPassword123!\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String employee=mapper.readTree(login).get("accessToken").asText();String created=mvc.perform(post("/api/purchase-requests").header("Authorization","Bearer "+employee).contentType(MediaType.APPLICATION_JSON).content("{\"supplierId\":1,\"lines\":[{\"productId\":1,\"quantity\":2,\"unitCost\":125}]}")).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("PENDING")).andReturn().getResponse().getContentAsString();long id=mapper.readTree(created).get("id").asLong();mvc.perform(patch("/api/purchase-requests/"+id+"/decision").header("Authorization","Bearer "+admin).contentType(MediaType.APPLICATION_JSON).content("{\"approved\":true,\"note\":\"Budget approved\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("APPROVED")).andExpect(jsonPath("$.purchaseOrderId").isNumber());mvc.perform(patch("/api/purchase-requests/"+id+"/decision").header("Authorization","Bearer "+admin).contentType(MediaType.APPLICATION_JSON).content("{\"approved\":true}")).andExpect(status().isConflict());}
}
